#include <iostream>
#include <string>
using namespace std;

struct Indirizzo {
    string citta;
    int cap;
};

struct Studente {
    string nome;
    int eta;
    Indirizzo indirizzo;
    int voti[2];
};

void compleanno(Studente &s) {
    s.eta++;
}

int main() {
    Studente classe[2] = {
        {"Ada", 17, {"Roma", 100}, {7, 8}},
        {"Luca", 18, {"Milano", 20100}, {6, 9}}
    };
    Studente copia = classe[0];
    compleanno(classe[0]);
    copia.voti[0] = 10;
    cout << classe[0].nome << " " << classe[0].eta << endl;
    cout << copia.nome << " " << copia.eta << " " << copia.voti[0] << endl;
}
